import React, { useState } from "react";
import api from "./api";

function EnrollmentForm() {
  const [studentId, setStudentId] = useState("");
  const [file, setFile] = useState(null);
  const [message, setMessage] = useState("");

  const submit = async (e) => {
    e.preventDefault();

    const formData = new FormData();

    // ⚠️ ton backend attend ces champs
    formData.append("photo_path", file?.name);
    formData.append("embedding", "BASE64_EMBEDDING_FROM_BACKEND");

    try {
      await api.post(`/students/${studentId}/enroll/`, formData, {
        headers: {
          "Content-Type": "multipart/form-data"
        }
      });

      setMessage("✅ Student enrolled successfully");
    } catch (error) {
      console.error(error);
      setMessage("❌ Error during enrollment");
    }
  };

  return (
    <div>
      <h2>Enroll Student</h2>

      <form onSubmit={submit}>
        <input
          placeholder="Student ID"
          value={studentId}
          onChange={(e) => setStudentId(e.target.value)}
        />

        <br /><br />

        <input
          type="file"
          onChange={(e) => setFile(e.target.files[0])}
        />

        <br /><br />

        <button>Enroll</button>
      </form>

      <p>{message}</p>
    </div>
  );
}

export default EnrollmentForm;
